76	function parseArgs(argv) {
77	  const result = {};
78	  for (let index = 0; index < argv.length; index += 1) {
79	    const arg = argv[index];
80	    if (!arg.startsWith("--")) {
81	      throw new Error(`unexpected argument: ${arg}`);
82	    }
83	    const key = arg.slice(2);
84	    const value = argv[index + 1];
85	    if (!value || value.startsWith("--")) {
86	      throw new Error(`missing value for --${key}`);
87	    }
88	    result[key] = value;
89	    index += 1;
90	  }
91	  return result;
92	}
