106	function loadDotEnvFile(path = ".env", environment = process.env) {
107	  if (!fs.existsSync(path)) {
108	    return {};
109	  }
110	
111	  const loaded = {};
112	  const text = fs.readFileSync(path, "utf8");
113	  for (const rawLine of text.split(/\r?\n/)) {
114	    const line = rawLine.trim();
115	    if (!line || line.startsWith("#")) {
116	      continue;
117	    }
118	
119	    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
120	    if (!match) {
121	      continue;
122	    }
123	
124	    const key = match[1];
125	    let value = match[2].trim();
126	    if (
127	      (value.startsWith('"') && value.endsWith('"'))
128	      || (value.startsWith("'") && value.endsWith("'"))
129	    ) {
130	      value = value.slice(1, -1);
131	    }
132	    loaded[key] = value;
133	    if (environment[key] === undefined) {
134	      environment[key] = value;
135	    }
136	  }
137	  return loaded;
138	}
