148	function jsonRpcError(id, code, message, data = undefined) {
149	  const error = {
150	    code: Number.isInteger(code) ? code : -32000,
151	    message,
152	  };
153	  if (data !== undefined) {
154	    error.data = data;
155	  }
156	  return { jsonrpc: "2.0", id, error };
157	}
158	
159	function jsonRpcErrorCode(error) {
160	  return Number.isInteger(error?.code) ? error.code : -32000;
161	}
