186	function isSessionActive(session, downstreamWs, generation) {
187	  return !session.closing
188	    && session.generation === generation
189	    && isWebSocketOpen(downstreamWs);
190	}
191	
192	function throwIfSessionInactive(session, downstreamWs, generation) {
193	  if (!isSessionActive(session, downstreamWs, generation)) {
194	    throw new Error("downstream session closed");
195	  }
196	}
