223	function assertFocusedRequestTargetsBoundThread(session, method, params = {}) {
224	  if (!session.upstream?.isOpen()) {
225	    throw new Error(`${method} requires thread/resume on this connection first`);
226	  }
227	  const boundThreadId = session.resumeParams?.threadId || null;
228	  const requestedThreadId = threadIDFromParams(params);
229	  if (!boundThreadId || !requestedThreadId) {
230	    throw relayError(`${method} requires threadId matching the active thread`, -32602, {
231	      subsystem: "live-upstream",
232	      reason: "missing_thread_id",
233	    });
234	  }
235	  if (requestedThreadId !== boundThreadId) {
236	    throw relayError(`${method} threadId does not match the active thread`, -32602, {
237	      subsystem: "live-upstream",
238	      reason: "thread_mismatch",
239	      requestedThreadIDHash: shortHash(requestedThreadId),
240	      activeThreadIDHash: shortHash(boundThreadId),
241	    });
242	  }
243	}
244	
245	function assertResumeResultMatchesRequestedThread(result, requestedThreadId) {
246	  const actualThreadId = result?.thread?.id;
247	  if (actualThreadId !== requestedThreadId) {
248	    throw relayError("thread/resume returned a different thread", -32000, {
249	      subsystem: "live-upstream",
250	      reason: "resume_thread_mismatch",
251	      requestedThreadIDHash: shortHash(requestedThreadId),
252	      actualThreadIDHash: shortHash(actualThreadId),
253	    });
254	  }
255	}
