257	function upstreamReconnectDelayMs(attempt) {
258	  const exponentialDelay = UPSTREAM_RECONNECT_DELAY_MS * (2 ** Math.max(0, attempt - 1));
259	  const jitter = Math.floor(Math.random() * (UPSTREAM_RECONNECT_JITTER_MS + 1));
260	  return exponentialDelay + jitter;
261	}
