263	async function resumeThread(config, params = {}, session, downstreamWs) {
264	  if (!params.threadId) {
265	    throw new Error("thread/resume requires threadId");
266	  }
267	  const resumeParams = liveResumeParams(params);
268	
269	  session.generation += 1;
270	  const generation = session.generation;
271	  session.retryTask = null;
272	  session.pendingServerRequests?.clear();
273	  session.upstream?.close();
274	  session.upstream = null;
275	
276	  const logger = relayLogger(config);
277	  const endpoint = await sessionRouterForConfig(config).endpointForThread(resumeParams.threadId);
278	  throwIfSessionInactive(session, downstreamWs, generation);
279	  const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
280	
281	  try {
282	    await initializeClient(client);
283	    throwIfSessionInactive(session, downstreamWs, generation);
284	    const result = await client.request("thread/resume", resumeParams);
285	    throwIfSessionInactive(session, downstreamWs, generation);
286	    assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
287	    session.upstream = client;
288	    session.resumeParams = { ...resumeParams };
289	    session.endpoint = endpoint;
290	    logger.info("thread_resume.succeeded", {
291	      subsystem: "live-upstream",
292	      hostId: config.hostId,
293	      threadId: resumeParams.threadId,
294	      endpointUrl: endpoint.url,
295	    });
296	    return result;
297	  } catch (error) {
298	    client.close();
299	    logger.warn("thread_resume.failed", {
300	      threadId: params.threadId,
301	      endpointUrl: endpoint.url,
302	      error,
303	    });
304	    config.statusTracker?.recordUpstreamError(error, {
305	      subsystem: "live-upstream",
306	      threadId: params.threadId,
307	      endpointUrl: endpoint.url,
308	    });
309	    throw error;
310	  }
311	}
