313	function makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation) {
314	  let client;
315	  client = new JsonRpcWebSocketClient(endpoint.url, {
316	    bearerToken: endpoint.bearerToken || null,
317	    logger: relayLogger(config),
318	    onNotification: (message) => {
319	      if (isSessionActive(session, downstreamWs, generation)) {
320	        sendJson(downstreamWs, message);
321	      }
322	    },
323	    onRequest: (message) => {
324	      if (isSessionActive(session, downstreamWs, generation)) {
325	        session.pendingServerRequests.set(String(message.id), {
326	          generation,
327	          threadId: message?.params?.threadId || session.resumeParams?.threadId || null,
328	          method: message.method,
329	        });
330	        sendJson(downstreamWs, message);
331	      }
332	    },
333	    onClose: () => {
334	      handleSessionUpstreamClose(config, session, downstreamWs, client);
335	    },
336	  });
337	  return client;
338	}
