340	function handleSessionUpstreamClose(config, session, downstreamWs, closedClient) {
341	  if (session.closing || session.upstream !== closedClient) {
342	    return;
343	  }
344	  session.upstream = null;
345	  session.pendingServerRequests?.clear();
346	  if (!isWebSocketOpen(downstreamWs)) {
347	    return;
348	  }
349	  if (!session.endpoint || !session.resumeParams?.threadId) {
350	    config.statusTracker?.recordUpstreamError(new Error("upstream closed"), {
351	      subsystem: "live-upstream",
352	    });
353	    downstreamWs.close(1011, "upstream closed");
354	    return;
355	  }
356	  if (session.retryTask) {
357	    return;
358	  }
359	  session.retryTask = recoverSessionUpstream(config, session, downstreamWs, session.generation);
360	}
361	
362	async function recoverSessionUpstream(config, session, downstreamWs, generation) {
363	  const endpoint = session.endpoint;
364	  const resumeParams = session.resumeParams;
365	  let lastError = null;
366	  config.statusTracker?.recordReconnect({
367	    active: true,
368	    attempts: 0,
369	  });
370	
371	  for (let attempt = 1; attempt <= UPSTREAM_RECONNECT_ATTEMPTS; attempt += 1) {
372	    if (session.closing || session.generation !== generation || !isWebSocketOpen(downstreamWs)) {
373	      session.retryTask = null;
374	      config.statusTracker?.recordReconnect({
375	        active: false,
376	        attempts: attempt - 1,
377	      });
378	      return;
379	    }
380	
381	    const client = makeSessionUpstreamClient(config, endpoint, session, downstreamWs, generation);
382	    try {
383	      await initializeClient(client);
384	      const result = await client.request("thread/resume", resumeParams);
385	      assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
386	      if (!isSessionActive(session, downstreamWs, generation)) {
387	        client.close();
388	        session.retryTask = null;
389	        return;
390	      }
391	      session.upstream = client;
392	      session.retryTask = null;
393	      config.statusTracker?.recordReconnect({
394	        active: false,
395	        attempts: attempt,
396	      });
397	      relayLogger(config).info("upstream.recovery_succeeded", {
398	        threadId: resumeParams.threadId,
399	        endpointUrl: endpoint.url,
400	        attempt,
401	      });
402	      return;
403	    } catch (error) {
404	      lastError = error;
405	      config.statusTracker?.recordUpstreamError(error, {
406	        subsystem: "live-upstream",
407	        threadId: resumeParams.threadId,
408	        endpointUrl: endpoint.url,
409	        attempt,
410	      });
411	      client.close();
412	      const delayMs = upstreamReconnectDelayMs(attempt);
413	      config.statusTracker?.recordReconnect({
414	        active: true,
415	        attempts: attempt,
416	        nextRetryAt: new Date(Date.now() + delayMs).toISOString(),
417	      });
418	      await sleep(delayMs);
419	    }
420	  }
421	
422	  session.retryTask = null;
423	  config.statusTracker?.recordReconnect({
424	    active: false,
425	    attempts: UPSTREAM_RECONNECT_ATTEMPTS,
426	  });
427	  relayLogger(config).error("upstream.recovery_failed", {
428	    threadId: resumeParams.threadId,
429	    endpointUrl: endpoint.url,
430	    error: lastError,
431	  });
432	  if (!session.closing && session.generation === generation && isWebSocketOpen(downstreamWs)) {
433	    downstreamWs.close(1011, "upstream recovery failed");
434	  }
435	}
