437	async function forwardToActiveUpstream(config, session, method, params = {}) {
438	  assertFocusedRequestTargetsBoundThread(session, method, params);
439	  relayLogger(config).info("focused_request.route_verified", {
440	    subsystem: "live-upstream",
441	    method,
442	    endpointUrl: session.endpoint?.url || null,
443	    threadIDHash: shortHash(params.threadId),
444	    activeThreadIDHash: shortHash(session.resumeParams?.threadId),
445	    generation: session.generation,
446	  });
447	  return session.upstream.request(method, params);
448	}
