450	async function handleRequest(config, method, params, session, downstreamWs) {
451	  switch (method) {
452	    case "initialize":
453	      return {
454	        userAgent: `codex_dock_relay/${RELAY_VERSION} (${os.type()} ${os.release()}; ${os.arch()})`,
455	        codexHome: process.env.CODEX_HOME || `${os.homedir()}/.codex`,
456	        platformFamily: "unix",
457	        platformOs: platformOs(),
458	        relayInstanceID: config.hostId,
459	      };
460	    case "thread/list":
461	      return aggregateThreadList(config, params || {});
462	    case "thread/loaded/list":
463	      return aggregateLoadedList(config, params || {});
464	    case "thread/read":
465	      return aggregateThreadRead(config, params || {});
466	    case "thread/turns/list":
467	      return listThreadTurns(config, params || {});
468	    case "thread/resume":
469	      return resumeThread(config, params || {}, session, downstreamWs);
470	    case "thread/archive":
471	      return archiveThread(config, params || {});
472	    case "thread/unarchive":
473	      return unarchiveThread(config, params || {});
474	    case "audio/transcription/start":
475	      return session.realtimeTranscription.start(params || {});
476	    case "audio/transcription/append":
477	      return session.realtimeTranscription.append(params || {});
478	    case "audio/transcription/commit":
479	      return session.realtimeTranscription.commit(params || {});
480	    case "audio/transcription/cancel":
481	      return session.realtimeTranscription.cancel(params || {});
482	    case "turn/start":
483	    case "turn/steer":
484	    case "turn/interrupt":
485	      return forwardToActiveUpstream(config, session, method, params || {});
486	    default:
487	      throw Object.assign(new Error(`unsupported method: ${method}`), {
488	        code: -32601,
489	      });
490	  }
491	}
