557	function startServer(config) {
558	  config.logger = relayLogger(config);
559	  const logger = config.logger;
560	  config.version = config.version || RELAY_VERSION;
561	  config.hostId = config.hostId || process.env.CODEX_DOCK_REAL_HOST_ID || os.hostname();
562	  config.hostName = config.hostName || process.env.CODEX_DOCK_REAL_HOST_NAME || config.hostId;
563	  config.openAIRealtimeTranscriptionModel = config.openAIRealtimeTranscriptionModel
564	    || DEFAULT_REALTIME_TRANSCRIPTION_MODEL;
565	  config.openAIRealtimeTranscriptionEndpoint = config.openAIRealtimeTranscriptionEndpoint
566	    || DEFAULT_REALTIME_TRANSCRIPTION_ENDPOINT;
567	  config.realtimeTranscriptionLanguage = config.realtimeTranscriptionLanguage
568	    || DEFAULT_REALTIME_TRANSCRIPTION_LANGUAGE;
569	  config.realtimeTranscriptionDelay = config.realtimeTranscriptionDelay
570	    || DEFAULT_REALTIME_TRANSCRIPTION_DELAY;
571	  config.statusTracker = config.statusTracker || createRelayStatusTracker();
572	  config.upstreamPool = config.upstreamPool || new UpstreamConnectionPool({
573	    logger,
574	    maxOpenByLabel: UPSTREAM_POOL_LIMITS,
575	  });
576	  config.liveStatusCache = liveStatusCacheForConfig(config);
577	  config.sessionRouter = sessionRouterForConfig(config);
