579	  config.phoneAuth = parsePhoneAuthMode(config.phoneAuth || DEFAULT_PHONE_AUTH);
580	  if (config.phoneAuth === "bearer" && !config.relayBearerToken) {
581	    throw new Error("relayBearerToken is required when phoneAuth is bearer");
582	  }
583	  logger.info("relay.starting", {
584	    subsystem: "relay",
585	    hostId: config.hostId,
586	    listenHost: config.listenHost,
587	    port: config.port,
588	    historyUrl: config.historyUrl,
589	    phoneAuth: config.phoneAuth,
590	    advertiseBonjour: config.advertiseBonjour !== false,
591	  });
592	
593	  const sessions = new Set();
594	  const downstreamSockets = new Set();
595	
596	  async function writeStatusResponse(response) {
597	    await checkRawAppServerHealth(config, config.statusTracker);
598	    response.writeHead(200, { "content-type": "application/json" });
599	    response.end(JSON.stringify(config.statusTracker.snapshot(
600	      config,
601	      runtimeSnapshot(config, sessions, downstreamSockets),
602	    )));
603	  }
