605	  function writeMetricsResponse(request, response) {
606	    if (writeLoopbackOnlyResponse(request, response)) {
607	      return;
608	    }
609	    response.writeHead(200, { "content-type": "application/json" });
610	    response.end(JSON.stringify(config.statusTracker.metricsSnapshot(
611	      config,
612	      runtimeSnapshot(config, sessions, downstreamSockets),
613	    )));
614	  }
