616	  function writeDebugSessionsResponse(request, response) {
617	    if (writeLoopbackOnlyResponse(request, response)) {
618	      return;
619	    }
620	    response.writeHead(200, { "content-type": "application/json" });
621	    response.end(JSON.stringify(config.statusTracker.debugSessionsSnapshot(
622	      config,
623	      runtimeSnapshot(config, sessions, downstreamSockets),
624	    )));
625	  }
626	
627	  const server = http.createServer((request, response) => {
628	    if (request.url === "/readyz") {
629	      response.writeHead(200, { "content-type": "application/json" });
630	      response.end(JSON.stringify({
631	        ok: true,
632	        service: "codex-dock-relay",
633	        auth: config.phoneAuth,
634	      }));
635	      return;
636	    }
637	    if (request.url === "/healthz") {
638	      response.writeHead(200, { "content-type": "application/json" });
639	      response.end(JSON.stringify({
640	        ok: true,
641	        service: "codex-dock-relay",
642	        auth: config.phoneAuth,
643	        staticConfig: {
644	          ok: true,
645	          historyConfigured: Boolean(config.historyUrl),
646	          transcriptionConfigured: Boolean(config.openAIRealtimeTranscriptionModel),
647	        },
648	      }));
