73	    private func relativeTime(since date: Date) -> String {
74	        let seconds = max(0, Int(now().timeIntervalSince(date)))
75	
76	        switch seconds {
77	        case 0..<60:
78	            return "now"
79	        case 60..<3_600:
80	            return "\(seconds / 60)m ago"
81	        case 3_600..<86_400:
82	            return "\(seconds / 3_600)h ago"
83	        default:
