28	public enum SessionSummaryMapper {
29	    public static func map(
30	        response: ThreadListResponseDTO,
31	        hostID: String
32	    ) -> SessionSummaryMappingResult {
33	        var summaries: [SessionSummary] = []
34	        var failures: [SessionSummaryMappingFailure] = []
35	
36	        for (index, thread) in response.data.enumerated() {
37	            switch map(thread: thread, hostID: hostID, index: index) {
38	            case .success(let summary):
39	                summaries.append(summary)
40	            case .failure(let failure):
41	                failures.append(failure)
42	            }
43	        }
44	
45	        return SessionSummaryMappingResult(summaries: summaries, failures: failures)
46	    }
47	
48	    private static func map(
49	        thread: ThreadDTO,
50	        hostID: String,
51	        index: Int
52	    ) -> Result<SessionSummary, SessionSummaryMappingFailure> {
53	        guard let threadID = nonEmpty(thread.id) else {
54	            return .failure(
55	                SessionSummaryMappingFailure(
56	                    index: index,
57	                    backendThreadID: nil,
58	                    reason: "missing thread id"
59	                )
60	            )
61	        }
62	        guard let sessionID = nonEmpty(thread.sessionId) else {
63	            return .failure(
64	                SessionSummaryMappingFailure(
65	                    index: index,
66	                    backendThreadID: threadID,
67	                    reason: "missing session id"
68	                )
69	            )
70	        }
71	        guard let timestamp = thread.updatedAt ?? thread.createdAt else {
72	            return .failure(
73	                SessionSummaryMappingFailure(
74	                    index: index,
75	                    backendThreadID: threadID,
76	                    reason: "missing last activity timestamp"
77	                )
78	            )
79	        }
80	
81	        let preview = nonEmpty(thread.preview)
82	        let shortEventSummary = nonEmpty(thread.latestSummary)
83	            ?? latestMeaningfulSummary(from: thread)
84	            ?? preview
85	        let displayTitle = displayTitle(
86	            name: thread.name,
87	            preview: preview,
88	            cwd: thread.cwd,
89	            threadID: threadID
90	        )
91	
92	        let summary = SessionSummary(
93	            id: HostScopedThreadID(hostID: hostID, threadID: threadID),
94	            backendSessionID: sessionID,
95	            displayTitle: displayTitle,
96	            status: status(from: thread.status),
97	            repository: repository(from: thread.gitInfo, cwd: thread.cwd),
98	            workingDirectory: text(from: thread.cwd),
99	            branch: text(from: thread.gitInfo?.branch),
100	            lastActivity: Date(timeIntervalSince1970: TimeInterval(timestamp)),
101	            shortEventSummary: shortEventSummary.map { .known(collapsed($0)) } ?? .unknown,
102	            origin: origin(from: thread)
103	        )
104	        return .success(summary)
105	    }
