107	    private static func latestMeaningfulSummary(from thread: ThreadDTO) -> String? {
108	        let messageEvents = ThreadEventNormalizer.events(from: thread).filter(isStoredMessageEvent)
109	        return messageEvents
110	            .max(by: eventPrecedes)
111	            .flatMap { nonEmpty($0.body) }
112	    }
113	
114	    private static func isStoredMessageEvent(_ event: ThreadEvent) -> Bool {
115	        event.kind == .userMessage || (event.kind == .agentMessage && event.title == "Agent message")
116	    }
117	
118	    private static func eventPrecedes(_ lhs: ThreadEvent, _ rhs: ThreadEvent) -> Bool {
119	        let lhsDate = lhs.displayGroupDate ?? lhs.date
120	        let rhsDate = rhs.displayGroupDate ?? rhs.date
121	        if let lhsDate, let rhsDate, lhsDate != rhsDate {
122	            return lhsDate < rhsDate
123	        }
124	        if lhsDate == nil, rhsDate != nil {
125	            return true
126	        }
127	        if lhsDate != nil, rhsDate == nil {
128	            return false
129	        }
130	
131	        let lhsTurn = lhs.turnSequence ?? Int.min
132	        let rhsTurn = rhs.turnSequence ?? Int.min
133	        if lhsTurn != rhsTurn {
134	            return lhsTurn < rhsTurn
135	        }
136	
137	        let lhsItem = lhs.itemSequence ?? Int.min
138	        let rhsItem = rhs.itemSequence ?? Int.min
139	        if lhsItem != rhsItem {
140	            return lhsItem < rhsItem
141	        }
142	
143	        let lhsEvent = lhs.eventSequence ?? Int.min
144	        let rhsEvent = rhs.eventSequence ?? Int.min
145	        return lhsEvent < rhsEvent
146	    }
