148	    private static func origin(from thread: ThreadDTO) -> SessionOrigin {
149	        let source = classifySource(thread.source)
150	        let threadSource = nonEmpty(thread.threadSource)
151	        let agentNickname = nonEmpty(thread.agentNickname)
152	        let agentRole = nonEmpty(thread.agentRole)
153	        let evidence = SessionOriginEvidence(
154	            sourceKind: source.sourceKind,
155	            rawSource: source.rawSource,
156	            threadSource: threadSource,
157	            agentNickname: agentNickname,
158	            agentRole: agentRole
159	        )
160	        let metadataSubtype = agentNickname != nil || agentRole != nil
161	            ? SessionAgentOriginSubtype.subAgentOther
162	            : subAgentSubtype(from: threadSource)
163	
164	        if let sourceOrigin = source.origin, sourceOrigin.kind == .agentOrAutomation {
165	            return sourceOrigin.replacingEvidence(evidence)
166	        }
167	
168	        if let sourceOrigin = source.origin,
169	           sourceOrigin.kind == .humanInteractive,
170	           metadataSubtype != nil {
171	            return .unknown(
172	                evidence: SessionOriginEvidence(
173	                    sourceKind: .unknown,
174	                    rawSource: evidence.rawSource,
175	                    threadSource: evidence.threadSource,
176	                    agentNickname: evidence.agentNickname,
177	                    agentRole: evidence.agentRole
178	                )
179	            )
180	        }
181	
182	        if let metadataSubtype {
183	            return .agentOrAutomation(subtype: metadataSubtype, evidence: evidence)
184	        }
185	
186	        if let sourceOrigin = source.origin {
187	            return sourceOrigin.replacingEvidence(evidence)
188	        }
189	
190	        return .unknown(evidence: evidence)
191	    }
