193	    private struct SourceClassification {
194	        let origin: SessionOrigin?
195	        let sourceKind: ThreadSourceKind?
196	        let rawSource: JSONValue?
197	    }
198	
199	    fileprivate enum RecognizedSourceSignal: Hashable {
200	        case human(SessionHumanOriginSubtype, sourceKind: ThreadSourceKind?)
201	        case automation(SessionAgentOriginSubtype, sourceKind: ThreadSourceKind)
202	        case unknown
203	
204	        var originKind: SessionOriginKind {
205	            switch self {
206	            case .human:
207	                return .humanInteractive
208	            case .automation:
209	                return .agentOrAutomation
210	            case .unknown:
211	                return .unknown
212	            }
213	        }
214	
215	        var sourceKind: ThreadSourceKind? {
216	            switch self {
217	            case .human(_, let sourceKind):
218	                return sourceKind
219	            case .automation(_, let sourceKind):
220	                return sourceKind
221	            case .unknown:
222	                return .unknown
223	            }
224	        }
225	    }
