227	    private static func classifySource(_ source: JSONValue?) -> SourceClassification {
228	        guard let source else {
229	            return SourceClassification(origin: nil, sourceKind: nil, rawSource: nil)
230	        }
231	
232	        let signals = source.recognizedSourceSignals
233	        if signals.isEmpty {
234	            return SourceClassification(
235	                origin: .unknown(),
236	                sourceKind: .unknown,
237	                rawSource: source
238	            )
239	        }
240	        if signals.contains(.unknown) {
241	            return SourceClassification(
242	                origin: .unknown(),
243	                sourceKind: .unknown,
244	                rawSource: source
245	            )
246	        }
247	
248	        let uniqueSignals = Set(signals)
249	        guard uniqueSignals.count == 1, let signal = signals.first else {
250	            return SourceClassification(
251	                origin: .unknown(),
252	                sourceKind: .unknown,
253	                rawSource: source
254	            )
255	        }
256	
257	        switch signal {
258	        case .human(let subtype, let sourceKind):
259	            return SourceClassification(
260	                origin: .humanInteractive(subtype: subtype),
261	                sourceKind: sourceKind,
262	                rawSource: source
263	            )
264	        case .automation(let subtype, let sourceKind):
265	            return SourceClassification(
266	                origin: .agentOrAutomation(subtype: subtype),
267	                sourceKind: sourceKind,
268	                rawSource: source
269	            )
270	        case .unknown:
271	            return SourceClassification(
272	                origin: .unknown(),
273	                sourceKind: .unknown,
274	                rawSource: source
275	            )
276	        }
277	    }
