394	    private static func repositoryName(fromOriginURL originURL: String) -> String? {
395	        let components = originURL.split { character in
396	            character == "/" || character == ":"
397	        }
398	        guard var name = components.last.map(String.init) else {
399	            return nil
400	        }
401	        if name.hasSuffix(".git") {
402	            name.removeLast(4)
403	        }
404	        return nonEmpty(name)
