407	    private static func lastPathComponent(_ path: String) -> String? {
408	        let trimmed = path.trimmingCharacters(in: .whitespacesAndNewlines)
409	        guard !trimmed.isEmpty else {
410	            return nil
411	        }
412	        return nonEmpty(URL(fileURLWithPath: trimmed).lastPathComponent)
