415	    private static func collapsed(_ value: String, maxLength: Int = 140) -> String {
416	        let firstLine = value
417	            .components(separatedBy: .newlines)
418	            .first ?? value
419	        let collapsed = firstLine
420	            .split(whereSeparator: { $0.isWhitespace })
421	            .joined(separator: " ")
422	        guard collapsed.count > maxLength else {
423	            return collapsed
424	        }
425	        let end = collapsed.index(collapsed.startIndex, offsetBy: max(0, maxLength - 3))
426	        return String(collapsed[..<end]) + "..."
427	    }
428	
429	    private static func nonEmpty(_ value: String?) -> String? {
430	        guard let value else {
431	            return nil
432	        }
433	        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
434	        return trimmed.isEmpty ? nil : trimmed
435	    }
436	}
