438	private extension JSONValue {
439	    var recognizedSourceSignals: [SessionSummaryMapper.RecognizedSourceSignal] {
440	        switch self {
441	        case .string(let value):
442	            return SessionSummaryMapper.sourceSignal(fromName: value).map { [$0] } ?? []
443	        case .object(let values):
444	            var signals: [SessionSummaryMapper.RecognizedSourceSignal] = []
445	            for key in values.keys where !key.isSubAgentSourceKey {
446	                if let signal = SessionSummaryMapper.sourceSignal(fromName: key) {
447	                    signals.append(signal)
448	                }
449	            }
450	            for key in ["type", "kind", "sourceKind", "source_kind", "subtype"] {
451	                if case .string(let value)? = values[key] {
452	                    if let signal = SessionSummaryMapper.sourceSignal(fromName: value) {
453	                        signals.append(signal)
454	                    }
455	                }
456	            }
457	            if case .string(let value)? = values["custom"] {
458	                if let signal = SessionSummaryMapper.sourceSignal(fromName: value) {
459	                    signals.append(signal)
460	                }
461	            }
462	            if let nestedSource = values["source"] {
463	                signals.append(contentsOf: nestedSource.recognizedSourceSignals)
464	            }
465	            if let subAgent = values["subAgent"] ?? values["subagent"] {
466	                signals.append(contentsOf: subAgent.recognizedSubAgentSignals)
467	            }
468	            return signals.removingDuplicates()
469	        case .array(let values):
470	            return values.flatMap(\.recognizedSourceSignals).removingDuplicates()
471	        case .null, .bool, .integer, .double:
472	            return []
473	        }
474	    }
475	
476	    var recognizedSubAgentSignals: [SessionSummaryMapper.RecognizedSourceSignal] {
477	        switch self {
478	        case .string(let value):
479	            return SessionSummaryMapper.sourceSignal(fromName: value).map { [$0] } ?? []
480	        case .object(let values):
481	            var signals: [SessionSummaryMapper.RecognizedSourceSignal] = []
482	            for key in values.keys {
483	                if let signal = SessionSummaryMapper.sourceSignal(fromName: key) {
484	                    signals.append(signal)
485	                }
486	            }
487	            for key in ["type", "kind", "variant", "subtype"] {
488	                if case .string(let value)? = values[key] {
489	                    if let signal = SessionSummaryMapper.sourceSignal(fromName: value) {
490	                        signals.append(signal)
491	                    }
492	                }
493	            }
494	            return signals.removingDuplicates()
495	        case .array(let values):
496	            return values.flatMap(\.recognizedSubAgentSignals).removingDuplicates()
497	        case .null, .bool, .integer, .double:
498	            return []
499	        }
500	    }
501	}
502	
503	private extension String {
504	    var isSubAgentSourceKey: Bool {
505	        switch SessionSummaryMapper.normalizedOriginToken(self) {
506	        case "subagent":
507	            return true
508	        default:
509	            return false
510	        }
511	    }
512	}
