514	private extension Sequence where Element: Equatable {
515	    func removingDuplicates() -> [Element] {
516	        var result: [Element] = []
517	        for element in self where !result.contains(element) {
518	            result.append(element)
519	        }
520	        return result
521	    }
522	}
