181	public enum DockHostConfigurationError: Error, Equatable, LocalizedError, Sendable {
182	    case missingEndpoint
183	    case invalidEndpoint(String)
184	    case invalidHost(String)
185	    case invalidPort(String)
186	    case duplicateHostID(String)
187	    case multipleHostsForSingleConfiguration(String)
188	    case rawAppServerEndpoint(String)
189	
190	    public var errorDescription: String? {
191	        switch self {
192	        case .missingEndpoint:
193	            return "Set CODEX_DOCK_HOSTS to one or more relay hosts like 192.168.50.117:\(CodexDockConstants.Ports.dockRelay)."
194	        case let .invalidEndpoint(value):
195	            return "Codex Dock relay endpoint must be host:port with no scheme, path, query, username, or password: \(value)"
196	        case let .invalidHost(value):
197	            return "Codex Dock relay host must not include a scheme, path, query, username, password, or whitespace: \(value)"
198	        case let .invalidPort(value):
199	            return "Codex Dock relay port must be an integer from 1 to 65535: \(value)"
200	        case let .duplicateHostID(hostID):
201	            return "CODEX_DOCK_HOSTS must not include the same endpoint more than once: \(hostID)"
202	        case let .multipleHostsForSingleConfiguration(value):
203	            return "Use HostRegistry.fromEnvironment for multiple CODEX_DOCK_HOSTS entries; a single host configuration can only use one host: \(value)"
204	        case let .rawAppServerEndpoint(value):
205	            return "Codex Dock app-facing hosts must point at the Dock relay on :\(CodexDockConstants.Ports.dockRelay), not the raw Codex app-server on :\(CodexDockConstants.Ports.rawAppServer): \(value)"
206	        }
207	    }
208	}
