211	    static func fromEnvironment(
212	        _ environment: [String: String] = ProcessInfo.processInfo.environment
213	    ) throws -> DockHostConfiguration {
214	        let endpoints = try DockRelayEndpoint.parseList(environment["CODEX_DOCK_HOSTS"])
215	        try endpoints.forEach { try $0.validateAppFacingRelayEndpoint() }
216	        guard let endpoint = endpoints.first, endpoints.count == 1 else {
217	            throw DockHostConfigurationError.multipleHostsForSingleConfiguration(
218	                endpoints.map(\.id).joined(separator: ",")
219	            )
220	        }
221	        let configuration = DockHostConfiguration(endpoint: endpoint)
222	        DockLog.hostConfiguration.notice("host configuration loaded host_id=\(configuration.id, privacy: .public) endpoint=\(DockLog.endpoint(configuration.webSocketURL), privacy: .public)")
223	        return configuration
224	    }
225	}
