57	public struct PersistedRelayHost: Codable, Equatable, Sendable {
58	    public let host: String
59	    public let port: Int
60	
61	    private enum CodingKeys: String, CodingKey {
62	        case host
63	        case port
64	    }
65	
66	    public init(endpoint: DockRelayEndpoint) {
67	        self.host = endpoint.host
68	        self.port = endpoint.port
69	    }
70	
71	    public init(from decoder: Decoder) throws {
72	        let allKeys = try decoder.container(keyedBy: AnyCodingKey.self)
73	        try Self.rejectUnexpectedKeys(
74	            Set(allKeys.allKeys.map(\.stringValue)),
75	            allowed: Set([CodingKeys.host.rawValue, CodingKeys.port.rawValue]),
76	            in: decoder
77	        )
78	        let container = try decoder.container(keyedBy: CodingKeys.self)
79	        self.host = try container.decode(String.self, forKey: .host)
80	        self.port = try container.decode(Int.self, forKey: .port)
81	    }
