96	        _ keys: Set<String>,
97	        allowed: Set<String>,
98	        in decoder: Decoder
99	    ) throws {
100	        guard let unexpected = keys.subtracting(allowed).sorted().first else {
101	            return
102	        }
103	        let context = DecodingError.Context(
104	            codingPath: decoder.codingPath,
105	            debugDescription: "Unexpected relay host key: \(unexpected)"
106	        )
107	        throw DecodingError.dataCorrupted(context)
108	    }
