290	        service.delegate = self
291	        DockLog.relayDiscovery.info("bonjour service found name=\(service.name, privacy: .public) service_count=\(self.services.count, privacy: .public)")
292	        service.resolve(withTimeout: CodexDockConstants.Dock.bonjourResolveTimeout)
293	    }
294	
295	    private func remove(_ service: NetService) {
296	        services.removeAll { $0 === service }
297	        let name = service.name
298	        relays.removeAll { $0.displayName == name }
299	        DockLog.relayDiscovery.info("bonjour service removed name=\(name, privacy: .public) relay_count=\(self.relays.count, privacy: .public)")
300	        onRelaysChanged?(relays)
301	    }
302	
303	    private func resolved(_ service: NetService) {
304	        guard let hostName = service.hostName,
305	              let relay = DiscoveredRelay(
306	                displayName: service.name,
307	                hostName: hostName,
308	                port: service.port,
309	                txtRecords: Self.txtRecords(from: service.txtRecordData())
310	              )
311	        else {
312	            DockLog.relayDiscovery.warning("bonjour service resolve ignored name=\(service.name, privacy: .public) reason=invalid_endpoint")
313	            return
314	        }
315	
316	        relays.removeAll { $0.id == relay.id }
317	        relays.append(relay)
318	        relays.sort { $0.displayName.localizedCaseInsensitiveCompare($1.displayName) == .orderedAscending }
319	        DockLog.relayDiscovery.notice("bonjour service resolved relay_id=\(relay.id, privacy: .public) name=\(relay.displayName, privacy: .public) endpoint=\(DockLog.endpoint(relay.endpoint.webSocketURL), privacy: .public) relay_count=\(self.relays.count, privacy: .public)")
320	        onRelaysChanged?(relays)
321	    }
322	
323	    private static func txtRecords(from data: Data?) -> [String: String] {
324	        guard let data else {
325	            return [:]
326	        }
327	        return NetService.dictionary(fromTXTRecord: data).reduce(into: [:]) { result, entry in
328	            result[entry.key] = String(data: entry.value, encoding: .utf8)
329	        }
330	    }
331	}
